window.WEEKS=[{w:1,size:{hi:"अभी गर्भ नहीं ठहरा, तैयारी का समय",en:"Not yet conceived, a time of preparation",ne:"अझै गर्भधारण गरिएको छैन, तयारीको समय"},growth:{hi:"गर्भावस्था की गिनती अंतिम मासिक धर्म के पहले दिन से होती है। पहले सप्ताह में गर्भाशय की परत मोटी हो रही है और अंडाणु परिपक्व हो रहा है। आयुर्वेद कहता है: शुद्ध शरीर और प्रसन्न मन ही स्वस्थ गर्भ की नींव है।",en:"Pregnancy is counted from the first day of your last period. In week 1 the uterine lining is thickening and the egg is maturing. Ayurveda says: a pure body and a joyful mind are the foundation of a healthy womb.",ne:"तपाईंको अन्तिम महिनावारीको पहिलो दिनबाट गर्भावस्था गणना गरिन्छ। पहिलो हप्तामा पाठेघरको अस्तर बाक्लो हुँदै जान्छ र अण्डा परिपक्व हुँदै जान्छ। आयुर्वेद भन्छ: शुद्ध शरीर र आनन्दित मन स्वस्थ गर्भको जग हो।"},sadhana:{hi:"इस सप्ताह का संकल्प: रोज़ सुबह 5 मिनट शांत बैठकर मन में कहें, “मैं स्वस्थ शिशु के स्वागत के लिए तैयार हूँ।”",en:"This week's resolve: sit quietly for 5 minutes each morning and say to yourself, “I am ready to welcome a healthy baby.”",ne:'यस हप्ताको संकल्प: हरेक बिहान ५ मिनेट चुपचाप बस्नुहोस् र आफैलाई भन्नुहोस्, "म स्वस्थ बच्चालाई स्वागत गर्न तयार छु।"'},tip:{hi:"सात्विक आहार शुरू करें: ताजे फल, हरी सब्जियां, दूध और पर्याप्त पानी।",en:"Begin a sattvik diet: fresh fruit, green vegetables, milk and plenty of water.",ne:"सात्विक आहार सुरु गर्नुहोस्: ताजा फलफूल, हरियो तरकारी, दूध र प्रशस्त पानी।"}},{w:2,size:{hi:"अंडाणु परिपक्व, निषेचन की प्रतीक्षा",en:"Egg maturing, awaiting conception",ne:"अण्डा परिपक्व हुँदै, गर्भधारणको पर्खाइमा"},growth:{hi:"दूसरे सप्ताह के अंत में अंडोत्सर्ग होता है: परिपक्व अंडाणु निषेचन के लिए तैयार हो जाता है। यह मिलन का सप्ताह है।",en:"At the end of week 2, ovulation occurs: the mature egg is ready for fertilization. This is the week of union.",ne:"दोस्रो हप्ताको अन्त्यमा, डिम्बाशय निषेचन हुन्छ: परिपक्व अण्डा निषेचनका लागि तयार हुन्छ। यो मिलनको हप्ता हो।"},sadhana:{hi:"गहरी सांसों का अभ्यास: रोज़ 10 धीमी गहरी सांसें लें। तनाव से मुक्त मन इस समय का सबसे बड़ा उपहार है।",en:"Deep breathing: take 10 slow, deep breaths daily. A mind free of stress is the greatest gift right now.",ne:"गहिरो सास फेर्नुहोस्: दैनिक १० पटक ढिलो, गहिरो सास लिनुहोस्। तनावमुक्त मन अहिलेको सबैभन्दा ठूलो उपहार हो।"},tip:{hi:"हल्का व्यायाम और प्रसन्नचित्त रहना, क्रोध और चिंता से दूरी रखें।",en:"Gentle exercise and a cheerful heart, keep anger and worry at a distance.",ne:"हल्का व्यायाम र प्रसन्न हृदय, रिस र चिन्तालाई टाढा राख्नुहोस्।"}},{w:3,size:{hi:"खसखस के दाने जितना",en:"Size of a poppy seed",ne:"खसखसको दानाको आकार"},growth:{hi:"चमत्कार हो चुका है! निषेचन के बाद एक कोशिका तेज़ी से विभाजित हो रही है और गर्भाशय की ओर बढ़ रही है। जीवन की यात्रा आरंभ।",en:"The miracle has happened! After fertilization, a single cell is dividing rapidly and traveling toward the uterus. The journey of life has begun.",ne:"चमत्कार भएको छ! निषेचन पछि, एउटा कोष द्रुत गतिमा विभाजित हुँदै गर्भाशयतिर यात्रा गरिरहेको छ। जीवनको यात्रा सुरु भएको छ।"},sadhana:{hi:"मौन के पल: दिन में एक बार 2 मिनट आंखें बंद करके अपने भीतर जागे नए जीवन का ध्यान करें।",en:"Moments of silence: once a day, close your eyes for 2 minutes and meditate on the new life awakening within you.",ne:"मौनताको क्षण: दिनमा एक पटक, २ मिनेट आँखा बन्द गर्नुहोस् र तपाईं भित्र जागृत नयाँ जीवनमा ध्यान गर्नुहोस्।"},tip:{hi:"फोलिक एसिड युक्त आहार (पालक, मेथी, दालें) इस समय अत्यंत महत्वपूर्ण है।",en:"Foods rich in folic acid (spinach, fenugreek, lentils) are vital at this stage.",ne:"यस चरणमा फोलिक एसिड (पालक, मेथी, दाल) युक्त खानेकुराहरू महत्त्वपूर्ण हुन्छन्।"}},{w:4,size:{hi:"तिल के दाने जितना (2 मिमी)",en:"Size of a sesame seed (2 mm)",ne:"तिलको दानाको आकार (२ मिमी)"},growth:{hi:"भ्रूण गर्भाशय की दीवार से जुड़ गया है। न्यूरल ट्यूब बन रही है, इसी से शिशु का मस्तिष्क और रीढ़ की हड्डी बनेगी।",en:"The embryo has attached to the uterine wall. The neural tube is forming, from it will grow the baby's brain and spine.",ne:"भ्रूण पाठेघरको भित्तामा जोडिएको छ। स्नायु नली बन्दैछ, त्यसबाट बच्चाको मस्तिष्क र मेरुदण्ड बढ्नेछ।"},sadhana:{hi:"कृतज्ञता: रोज़ सुबह सूर्य की ओर मुख करके 3 बार कहें, “इस नए जीवन के लिए धन्यवाद।”",en:"Gratitude: every morning, face the sun and say 3 times, “Thank you for this new life.”",ne:'कृतज्ञता: हरेक बिहान, सूर्यतिर फर्केर ३ पटक भन्नुहोस्, "यो नयाँ जीवनको लागि धन्यवाद।"'},tip:{hi:"धूम्रपान, शराब और तेज़ दवाओं से पूर्ण दूरी, ये सप्ताह सबसे नाजुक होते हैं।",en:"Complete distance from smoking, alcohol and strong medicines, these weeks are the most delicate.",ne:"धूम्रपान, मदिरा र कडा औषधिबाट पूर्ण दूरी, यी हप्ताहरू सबैभन्दा नाजुक हुन्छन्।"}},{w:5,size:{hi:"तिल जितना (3 मिमी)",en:"Sesame-seed sized (3 mm)",ne:"तिलको आकार (३ मिमी)"},growth:{hi:"एक अद्भुत घटना: इस सप्ताह शिशु का हृदय धड़कने लगता है, लगभग 110 धड़कन प्रति मिनट! हाथ-पैर की नन्ही कलियां भी दिखने लगी हैं।",en:"A wonder: this week your baby's heart begins to beat, about 110 beats per minute! Tiny arm and leg buds are appearing.",ne:"एउटा अचम्मको कुरा: यस हप्ता तपाईंको बच्चाको मुटु धड्कन थाल्छ, प्रति मिनेट लगभग ११० धड्कन! हात र खुट्टाका स-साना कोपिलाहरू देखा पर्दैछन्।"},sadhana:{hi:"अपने हृदय पर हाथ रखकर धीरे से 11 बार “ॐ” बोलें। यह आदि ध्वनि आपके शिशु तक पहुंचती है।",en:"Place your hand on your heart and softly chant “Om” 11 times. This primal sound reaches your baby.",ne:'आफ्नो हात आफ्नो मुटुमा राख्नुहोस् र ११ पटक "ॐ" जप्नुहोस्। यो आदिम ध्वनि तपाईंको बच्चासम्म पुग्छ।'},tip:{hi:"अब गर्भावस्था की पुष्टि का समय है, डॉक्टर से पहला परामर्श लें।",en:"Time to confirm the pregnancy, schedule your first doctor's visit.",ne:"गर्भावस्था पुष्टि गर्ने समय, आफ्नो पहिलो डाक्टरको भ्रमणको तालिका बनाउनुहोस्।"}},{w:6,size:{hi:"मसूर की दाल / मटर जितना (6 मिमी)",en:"Size of a lentil / pea (6 mm)",ne:"दाल / मटरको आकार (६ मिमी)"},growth:{hi:"नाक, मुंह और कान की रचना शुरू हो गई है। हृदय अब नियमित धड़क रहा है और शरीर में रक्त संचार आरंभ हो चुका है।",en:"The nose, mouth and ears begin to take shape. The heart now beats rhythmically and blood circulation has begun.",ne:"नाक, मुख र कानले आकार लिन थाल्छन्। मुटु अब लयबद्ध रूपमा धड्किन्छ र रक्तसञ्चार सुरु भएको छ।"},sadhana:{hi:"गायत्री मंत्र का श्रवण आरंभ करें, रोज़ सुबह 3 बार सुनें या बोलें। मंत्र पृष्ठ पर ऑडियो उपलब्ध है।",en:"Begin listening to the Gayatri mantra, hear or chant it 3 times every morning. Audio is on the mantras page.",ne:"गायत्री मन्त्र सुन्न सुरु गर्नुहोस्, हरेक बिहान ३ पटक सुन्नुहोस् वा जप गर्नुहोस्। अडियो मन्त्र पृष्ठमा छ।"},tip:{hi:"जी मिचलाना सामान्य है, थोड़ा-थोड़ा करके हल्का भोजन लें, अदरक की चाय लाभकारी है।",en:"Morning sickness is normal, eat small, light meals often; ginger tea helps.",ne:"बिहानको समयमा लाग्ने बानी सामान्य हो, थोरै थोरै, हल्का खाना बारम्बार खानुहोस्; अदुवा चियाले मद्दत गर्छ।"}},{w:7,size:{hi:"ब्लूबेरी जितना (1.3 सेमी)",en:"Size of a blueberry (1.3 cm)",ne:"ब्लूबेरीको आकार (१.३ सेमी)"},growth:{hi:"मस्तिष्क तेज़ी से विकसित हो रहा है, हर मिनट लाखों नई कोशिकाएं बन रही हैं! हाथ-पैर की उंगलियां आकार लेने लगी हैं।",en:"The brain is developing rapidly, millions of new cells every minute! Fingers and toes are beginning to form.",ne:"मस्तिष्क द्रुत गतिमा विकास भइरहेको छ, हरेक मिनेट लाखौं नयाँ कोषहरू! औंलाहरू र औंलाहरू बन्न थालेका छन्।"},sadhana:{hi:"शिशु से संवाद: रोज़ कुछ पल पेट पर हाथ रखकर मीठे शब्दों में अपने दिन के बारे में बताएं। आपकी आवाज़ ही उसका पहला संसार है।",en:"Talk to your baby: every day, rest your hand on your belly and sweetly tell it about your day. Your voice is its first world.",ne:"आफ्नो बच्चासँग कुरा गर्नुहोस्: हरेक दिन, आफ्नो पेटमा हात राख्नुहोस् र मीठो स्वरमा आफ्नो दिनको बारेमा बताउनुहोस्। तपाईंको आवाज नै यसको पहिलो संसार हो।"},tip:{hi:"पर्याप्त नींद लें, इस समय शरीर दिन-रात निर्माण कार्य में लगा है।",en:"Get plenty of sleep, your body is doing construction work day and night.",ne:"प्रशस्त निद्रा लिनुहोस्, तपाईंको शरीरले दिनरात निर्माण कार्य गरिरहेको छ।"}},{w:8,size:{hi:"राजमा / रसभरी जितना (1.6 सेमी)",en:"Size of a kidney bean / raspberry (1.6 cm)",ne:"किडनी बीन / रास्पबेरीको आकार (१.६ सेमी)"},growth:{hi:"सभी मुख्य अंगों की नींव पड़ चुकी है! भ्रूण अब हिलने-डुलने लगा है (आपको अभी महसूस नहीं होगा)।",en:"The foundations of all major organs are laid! The embryo has begun to move (you won't feel it yet).",ne:"सबै प्रमुख अंगहरूको जग बसालिएको छ! भ्रूण चल्न थालेको छ (तपाईंले अझै महसुस गर्नुहुने छैन)।"},sadhana:{hi:"अभिमन्यु की कथा पढ़ें या सुनें, गर्भ में सीखने की परंपरा का सबसे सुंदर उदाहरण महाभारत से।",en:"Read or listen to the story of Abhimanyu, the Mahabharata's most beautiful example of learning in the womb.",ne:"महाभारतको गर्भमा सिकाइको सबैभन्दा सुन्दर उदाहरण अभिमन्युको कथा पढ्नुहोस् वा सुन्नुहोस्।"},tip:{hi:"पहला अल्ट्रासाउंड आमतौर पर इसी समय होता है, अपने डॉक्टर से पूछें।",en:"The first ultrasound usually happens around now, ask your doctor.",ne:"पहिलो अल्ट्रासाउन्ड सामान्यतया अहिले हुन्छ, आफ्नो डाक्टरलाई सोध्नुहोस्।"}},{w:9,size:{hi:"अंगूर / चेरी जितना (2.3 सेमी)",en:"Size of a grape / cherry (2.3 cm)",ne:"अंगुर / चेरीको आकार (२.३ सेमी)"},growth:{hi:"उंगलियां अब अलग-अलग दिखती हैं, पलकें बन रही हैं। अब शिशु वैज्ञानिक भाषा में “फीटस” कहलाता है।",en:"Fingers are now distinct, eyelids are forming. Your baby is now scientifically called a “fetus”.",ne:'औंलाहरू अब छुट्टै देखिन्छन्, आँखाको परेलाहरू बनिरहेका छन्। तपाईंको बच्चालाई अब वैज्ञानिक रूपमा "भ्रूण" भनिन्छ।'},sadhana:{hi:"संगीत चिकित्सा: रोज़ 15 मिनट शांत शास्त्रीय संगीत या भजन सुनें। राग यमन और भैरवी गर्भ के लिए विशेष शुभ माने गए हैं।",en:"Music therapy: listen to 15 minutes of calm classical music or bhajans daily. Raag Yaman and Bhairavi are considered especially auspicious for the womb.",ne:"संगीत चिकित्सा: दैनिक १५ मिनेट शान्त शास्त्रीय संगीत वा भजन सुन्नुहोस्। राग यमन र भैरवी गर्भको लागि विशेष गरी शुभ मानिन्छ।"},tip:{hi:"पानी खूब पिएं, बढ़ता रक्त आयतन हाइड्रेशन मांगता है।",en:"Drink plenty of water, your growing blood volume demands hydration.",ne:"प्रशस्त पानी पिउनुहोस्, तपाईंको बढ्दो रगतको मात्राले हाइड्रेशनको आवश्यकता पर्दछ।"}},{w:10,size:{hi:"स्ट्रॉबेरी जितना (3 सेमी)",en:"Size of a strawberry (3 cm)",ne:"स्ट्रबेरीको आकार (३ सेमी)"},growth:{hi:"महत्वपूर्ण अंग काम करने लगे हैं, गुर्दे मूत्र बना रहे हैं, यकृत रक्त कोशिकाएं बना रहा है। कोहनी अब मुड़ सकती है!",en:"Vital organs have started working, the kidneys make urine, the liver makes blood cells. The elbows can bend!",ne:"महत्त्वपूर्ण अंगहरूले काम गर्न थालेका छन्, मिर्गौलाले पिसाब बनाउँछ, कलेजोले रक्तकोष बनाउँछ। कुहिनाहरू मोडिन सक्छन्!"},sadhana:{hi:"परिवार के साथ प्रार्थना: शाम को दीप जलाकर सब मिलकर “शुभं करोति” बोलें, सामूहिक ध्वनि का प्रभाव गहरा होता है।",en:"Pray with family: light a lamp in the evening and chant “Shubham Karoti” together, collective sound has a deep effect.",ne:'परिवारसँग प्रार्थना गर्नुहोस्: साँझमा बत्ती बाल्नुहोस् र सँगै "शुभम करोती" जप गर्नुहोस्, सामूहिक ध्वनिले गहिरो प्रभाव पार्छ।'},tip:{hi:"कब्ज़ से बचने के लिए फाइबर युक्त आहार (फल, सलाद) लें।",en:"To avoid constipation, eat fiber-rich food (fruit, salads).",ne:"कब्जियतबाट बच्नको लागि, फाइबरयुक्त खाना (फलफूल, सलाद) खानुहोस्।"}},{w:11,size:{hi:"अंजीर जितना (4 सेमी)",en:"Size of a fig (4 cm)",ne:"नेभाराको आकार (४ सेमी)"},growth:{hi:"दांतों की जड़ें और नाखूनों की नींव बन रही है। शिशु अब “सांस” लेने का अभ्यास कर रहा है, एमनियोटिक द्रव के साथ!",en:"Tooth roots and nail beds are forming. Your baby is now practicing “breathing”, with amniotic fluid!",ne:'दाँतको जरा र नङको पातहरू बनिरहेका छन्। तपाईंको बच्चाले अब एम्नियोटिक तरल पदार्थको साथ "सास फेर्ने" अभ्यास गरिरहेको छ!'},sadhana:{hi:"सात्विक आहार पर ध्यान: ताजे फल, दूध, घी, मूंग की दाल, आयुर्वेद इन्हें गर्भ के लिए अमृत मानता है।",en:"Focus on sattvik food: fresh fruit, milk, ghee, moong dal, Ayurveda calls these nectar for the womb.",ne:"सात्विक खानामा ध्यान दिनुहोस्: ताजा फलफूल, दूध, घिउ, मुगको दाल, आयुर्वेदले यी सबैलाई गर्भको लागि अमृत भन्छ।"},tip:{hi:"वजन धीरे-धीरे बढ़ना सामान्य है, “दो के लिए खाना” एक मिथक है, संतुलित खाएं।",en:"Slow weight gain is normal, “eating for two” is a myth; eat balanced meals.",ne:'ढिलो तौल बढ्नु सामान्य हो, "दुई जनाको लागि खाना खानु" एउटा मिथक हो; सन्तुलित खाना खानुहोस्।'}},{w:12,size:{hi:"नींबू जितना (5–6 सेमी)",en:"Size of a lime (5–6 cm)",ne:"कागतीको आकार (५-६ सेन्टिमिटर)"},growth:{hi:"प्रतिवर्त क्रियाएं शुरू, शिशु अब अंगूठा चूस सकता है! स्वर तंत्र और कान बन रहे हैं, और कुछ ही हफ्तों में वह आपकी आवाज़ सुन सकेगा।",en:"Reflexes begin, and your baby can suck its thumb! The vocal cords and ears are forming, and in a few more weeks your baby will hear your voice.",ne:"रिफ्लेक्स सुरु हुन्छ, र तपाईंको बच्चाले आफ्नो औंला चुस्न सक्छ! भोकल कर्ड र कानहरू बन्दैछन्, र केही हप्तामा तपाईंको बच्चाले तपाईंको आवाज सुन्नेछ।"},sadhana:{hi:"गायत्री मंत्र: “ॐ भूर्भुवः स्वः…”, रोज़ 11 बार। आपकी ध्वनि ही शिशु का पहला संगीत है।",en:"Gayatri mantra: “Om Bhur Bhuvah Svah…”, 11 times daily. Your voice is your baby's first music.",ne:"गायत्री मन्त्र: “ओम भूर भुवः स्वः…”, दिनको ११ पटक। तपाईंको आवाज तपाईंको बच्चाको पहिलो संगीत हो।"},tip:{hi:"पहली तिमाही पूरी होने वाली है, बधाई! अब ऊर्जा धीरे-धीरे लौटेगी।",en:"The first trimester is nearly complete, congratulations! Your energy will slowly return.",ne:"पहिलो त्रैमासिक लगभग पूरा भएको छ, बधाई छ! तपाईंको ऊर्जा बिस्तारै फर्कनेछ।"}},{w:13,size:{hi:"नींबू जितना (७-८ सेमी)",en:"Size of a lemon (7-8 cm)",ne:"कागतीको आकार (७-८ सेन्टिमिटर)"},growth:{hi:"पहली तिमाही का समापन! नाखून बन रहे हैं, स्वर तंत्र विकसित हो रहा है और शिशु अब निगल सकता है।",en:"The first trimester ends! Fingernails are forming, the vocal cords are developing, and your baby can now swallow.",ne:"पहिलो त्रैमासिक समाप्त हुन्छ! औंलाका नङहरू बनिरहेका छन्, स्वरयन्त्रहरू विकास भइरहेका छन्, र तपाईंको बच्चाले अब निल्न सक्छ।"},sadhana:{hi:"परिवार के साथ आशीर्वाद समारोह: सब मिलकर मां की गोद भरें और शिशु के स्वागत की कामना करें।",en:"Celebrate with a family blessing: gather everyone, bless the mother's lap, and wish the baby welcome.",ne:"पारिवारिक आशीर्वादका साथ उत्सव मनाउनुहोस्: सबैलाई भेला गर्नुहोस्, आमाको काखमा आशीर्वाद दिनुहोस्, र बच्चालाई स्वागत गर्नुहोस्।"},tip:{hi:"ऊर्जा लौट रही है, अब रोज़ हल्की सैर शुरू करें।",en:"Your energy is returning, begin a gentle daily walk now.",ne:"तपाईंको ऊर्जा फर्किँदैछ, अब दैनिक हल्का हिँडाइ सुरु गर्नुहोस्।"}},{w:14,size:{hi:"आड़ू जितना (८-९ सेमी)",en:"Size of a peach (8-9 cm)",ne:"आरुको आकार (८-९ सेन्टिमिटर)"},growth:{hi:"गुर्दे मूत्र बनाने लगे हैं, चेहरे पर भाव आते हैं और शरीर पर महीन रोएं (लैनुगो) उग आए हैं।",en:"The kidneys are making urine, facial expressions appear, and fine lanugo hair covers the body.",ne:"मिर्गौलाले पिसाब निकालिरहेको छ, अनुहारको भाव देखिन्छ, र मसिना लानुगो रौंले शरीर ढाकिएको छ।"},sadhana:{hi:"रामायण या भगवद्गीता की कथाएं ज़ोर से पढ़ना शुरू करें, शिशु को अच्छे संस्कारों की नींव मिलेगी।",en:"Begin reading Ramayana or Bhagavad Gita stories aloud; your baby receives the foundation of good values.",ne:"रामायण वा भागवत गीताका कथाहरू ठूलो स्वरमा पढ्न सुरु गर्नुहोस्; तपाईंको बच्चाले असल मूल्यमान्यताको जग प्राप्त गर्छ।"},tip:{hi:"नाक से खून आना सामान्य हो सकता है, बढ़ा रक्त प्रवाह इसका कारण है।",en:"Nosebleeds can be normal now, caused by extra blood flow.",ne:"नाकबाट रगत बग्नु अब सामान्य हुन सक्छ, अतिरिक्त रक्त प्रवाहको कारणले।"}},{w:15,size:{hi:"सेब जितना (१० सेमी)",en:"Size of an apple (10 cm)",ne:"स्याउको आकार (१० सेमी)"},growth:{hi:"पैर हाथों से लंबे हो गए हैं, शिशु प्रकाश महसूस करता है और सांस लेने का अभ्यास कर रहा है।",en:"The legs are now longer than the arms; your baby senses light and is practicing breathing movements.",ne:"अब खुट्टाहरू पाखुराभन्दा लामा छन्; तपाईंको बच्चाले प्रकाश महसुस गर्छ र श्वासप्रश्वासको अभ्यास गरिरहेको छ।"},sadhana:{hi:"रोज़ लोरी गाएं, आपकी मधुर आवाज़ शिशु के मन को शांत करती है।",en:"Sing lullabies daily; your sweet voice soothes your baby's mind.",ne:"दैनिक लोरी गाउनुहोस्; तपाईंको मीठो आवाजले तपाईंको बच्चाको मनलाई शान्त पार्छ।"},tip:{hi:"त्वचा दमक रही है, पेट पर मॉइस्चराइज़र लगाएं।",en:"Your skin is glowing; moisturize your belly.",ne:"तपाईंको छाला चम्किलो छ; आफ्नो पेटलाई मोइस्चराइज गर्नुहोस्।"}},{w:16,size:{hi:"एवोकाडो जितना (११-१२ सेमी)",en:"Size of an avocado (11-12 cm)",ne:"एभोकाडोको आकार (११-१२ सेन्टिमिटर)"},growth:{hi:"आंखें हिल सकती हैं, तंत्रिका तंत्र सक्रिय है और पहली हलचल महसूस हो सकती है।",en:"The eyes can move, the nervous system is active, and the first flutters may be felt.",ne:"आँखा चल्न सक्छन्, स्नायु प्रणाली सक्रिय छ, र पहिलो फड्को महसुस हुन सक्छ।"},sadhana:{hi:"पारिवारिक मूल्यों को ज़ोर से बोलें, शिशु के नाम का जाप करें।",en:"Speak your family values aloud and chant your baby's name.",ne:"आफ्नो पारिवारिक मूल्यमान्यताहरू ठूलो स्वरमा बोल्नुहोस् र आफ्नो बच्चाको नाम जप्नुहोस्।"},tip:{hi:"हल्की फड़फड़ाहट (क्विकनिंग) शुरू हो सकती है, ध्यान दें।",en:"Light flutters (quickening) may begin; pay attention.",ne:"हल्का फड्को (छिटो) सुरु हुन सक्छ; ध्यान दिनुहोस्।"}},{w:17,size:{hi:"नाशपाती जितना (१३ सेमी)",en:"Size of a pear (13 cm)",ne:"नास्पातीको आकार (१३ सेमी)"},growth:{hi:"शरीर में वसा जमा हो रही है, पसीने की ग्रंथियां बन रही हैं और कंकाल हड्डी में बदल रहा है।",en:"Fat is accumulating, sweat glands are developing, and the skeleton is hardening into bone.",ne:"बोसो जम्मा हुँदैछ, पसिना ग्रन्थीहरू विकास हुँदैछन्, र कंकाल हड्डीमा परिणत हुँदैछ।"},sadhana:{hi:"पिता भी शिशु से बात करें और गाएं, दो आवाज़ें दोगुना आनंद देती हैं।",en:"The father should also talk and sing to the baby; two voices bring double joy.",ne:"बुबाले पनि बच्चासँग कुरा गर्नुपर्छ र गीत गाउनु पर्छ; दुई आवाजले दोहोरो आनन्द ल्याउँछ।"},tip:{hi:"कमर दर्द हो सकता है, सीधी मुद्रा में बैठें और खड़े हों।",en:"Backaches may start; sit and stand with good posture.",ne:"ढाड दुख्न सक्छ; राम्रो आसनमा बस्नुहोस् र उभिनुहोस्।"}},{w:18,size:{hi:"शिमला मिर्च जितना (१४ सेमी)",en:"Size of a bell pepper (14 cm)",ne:"शिमला खुर्सानीको आकार (१४ सेमी)"},growth:{hi:"कान अपनी जगह पर आ गए हैं, सुनना शुरू हो गया है! तेज़ आवाज़ पर शिशु चौंक सकता है।",en:"The ears are in place and hearing begins! Your baby may startle at loud sounds.",ne:"कानहरू ठाउँमा हुन्छन् र सुन्न सुरु हुन्छ! तपाईंको बच्चा ठूलो आवाज सुनेर तर्सन सक्छ।"},sadhana:{hi:"अब रोज़ मंत्रों का जाप ज़ोर से करें, शिशु सचमुच सुन सकता है।",en:"Begin chanting mantras aloud daily now; your baby can truly hear.",ne:"अबदेखि दैनिक ठूलो स्वरमा मन्त्र जप गर्न सुरु गर्नुहोस्; तपाईंको बच्चाले साँच्चै सुन्न सक्छ।"},tip:{hi:"धीरे-धीरे उठें, चक्कर आना सामान्य है।",en:"Rise slowly; dizziness is common.",ne:"बिस्तारै उठ्नुहोस्; चक्कर लाग्नु सामान्य हो।"}},{w:19,size:{hi:"टमाटर जितना (१५ सेमी)",en:"Size of a tomato (15 cm)",ne:"गोलभेडाको आकार (१५ सेमी)"},growth:{hi:"मस्तिष्क इंद्रियों का मानचित्र बना रहा है और त्वचा पर वर्निक्स की रक्षात्मक परत चढ़ रही है।",en:"The brain is mapping the senses, and a protective vernix coating covers the skin.",ne:"मस्तिष्कले इन्द्रियहरूको नक्साङ्कन गरिरहेको छ, र सुरक्षात्मक भर्निक्स कोटिंगले छालालाई ढाक्छ।"},sadhana:{hi:"विविध पौष्टिक भोजन खाएं, हर स्वाद शिशु तक पहुंचता है।",en:"Eat varied, healthy foods; every flavor reaches your baby.",ne:"विविध, स्वस्थकर खाना खानुहोस्; हरेक स्वाद तपाईंको बच्चासम्म पुग्छ।"},tip:{hi:"पैरों में ऐंठन हो सकती है, सोने से पहले हल्का स्ट्रेच करें।",en:"Leg cramps may occur; do a gentle stretch before bed.",ne:"खुट्टा बाउँडिन सक्छ; सुत्नुअघि हल्का स्ट्रेचिङ गर्नुहोस्।"}},{w:20,size:{hi:"केला जितना (२५ सेमी, ३०० ग्राम)",en:"Size of a banana (25 cm, 300 g)",ne:"केराको आकार (२५ सेमी, ३०० ग्राम)"},growth:{hi:"आधी यात्रा पूरी! एनाटॉमी स्कैन का समय है और शिशु अब निगलने का अभ्यास कर रहा है।",en:"Halfway there! Time for the anatomy scan, and your baby is practicing swallowing.",ne:"आधा बाटो पुग्यो! शरीर रचना स्क्यानको समय भयो, र तपाईंको बच्चा निल्ने अभ्यास गर्दैछ।"},sadhana:{hi:"पुंसवन संस्कार का पारंपरिक समय, परिवार के साथ छोटा उत्सव मनाएं।",en:"The traditional time for the Punsavana sanskar; celebrate with family.",ne:"पुंसावन संस्कारको परम्परागत समय; परिवारसँग मनाउनुहोस्।"},tip:{hi:"इसी सप्ताह एनाटॉमी स्कैन करवाएं।",en:"Get your anatomy scan this week.",ne:"यस हप्ता आफ्नो शरीर रचना स्क्यान गराउनुहोस्।"}},{w:21,size:{hi:"गाजर जितना (२६ सेमी)",en:"Size of a carrot (26 cm)",ne:"गाजरको आकार (२६ सेमी)"},growth:{hi:"आंखों की तेज़ गति शुरू, अस्थि मज्जा रक्त कोशिकाएं बना रही है।",en:"Rapid eye movements begin, and bone marrow is making blood cells.",ne:"आँखाको गति तीव्र हुन थाल्छ, र हड्डीको मज्जाले रक्त कोषहरू बनाउँदैछ।"},sadhana:{hi:"प्रह्लाद की कथा पढ़ें, गर्भ में भक्ति की शक्ति का अमर उदाहरण।",en:"Read the story of Prahlad, the timeless example of devotion's power in the womb.",ne:"गर्भमा भक्तिको शक्तिको कालातीत उदाहरण, प्रह्लादको कथा पढ्नुहोस्।"},tip:{hi:"पेट बढ़ने से त्वचा में खुजली हो सकती है, तेल लगाएं।",en:"Itchy skin may come as the belly grows; apply oil.",ne:"पेट बढ्दै जाँदा छाला चिलाउन सक्छ; तेल लगाउनुहोस्।"}},{w:22,size:{hi:"नारियल जितना (२८ सेमी)",en:"Size of a coconut (28 cm)",ne:"नरिवलको आकार (२८ सेमी)"},growth:{hi:"भौहें दिख रही हैं, होंठ स्पष्ट हैं और शिशु चीज़ें पकड़ सकता है।",en:"Eyebrows are visible, lips are distinct, and your baby can grasp.",ne:"आँखीभौं देखिन्छन्, ओठहरू स्पष्ट देखिन्छन्, र तपाईंको बच्चाले बुझ्न सक्छ।"},sadhana:{hi:"रोज़ हल्का गर्भ संस्कार संगीत सुनें, शांत धुनें शिशु को प्रिय लगती हैं।",en:"Listen to gentle Garbh Sanskar music daily; calm melodies delight your baby.",ne:"हरेक दिन कोमल गर्भ संस्कार संगीत सुन्नुहोस्; शान्त धुनले तपाईंको बच्चालाई आनन्दित बनाउँछ।"},tip:{hi:"स्ट्रेच मार्क्स दिख सकते हैं, नियमित तेल मालिश करें।",en:"Stretch marks may appear; massage with oil regularly.",ne:"स्ट्रेच मार्क्स देखा पर्न सक्छन्; नियमित रूपमा तेलले मालिस गर्नुहोस्।"}},{w:23,size:{hi:"बड़े आम जितना (२९ सेमी, ५०० ग्राम)",en:"Size of a large mango (29 cm, 500 g)",ne:"ठूलो आँपको आकार (२९ सेमी, ५०० ग्राम)"},growth:{hi:"सुनने की शक्ति तेज़, शिशु मां की आवाज़ पहचानता है और फेफड़े विकसित हो रहे हैं।",en:"Hearing is sharper; your baby recognizes your voice, and the lungs are developing.",ne:"सुन्ने क्षमता तेज हुन्छ; तपाईंको बच्चाले तपाईंको आवाज चिन्छ, र फोक्सो विकास हुँदैछ।"},sadhana:{hi:"पिता रोज़ ज़ोर से पढ़ें, शिशु दोनों आवाज़ों से जुड़ता है।",en:"The father should read aloud daily; your baby bonds with both voices.",ne:"बुबाले दैनिक ठूलो स्वरले पढ्नुपर्छ; तपाईंको बच्चाले दुवै आवाजसँग घुलमिल हुन्छ।"},tip:{hi:"टखने सूज सकते हैं, पैर ऊपर उठाकर आराम करें।",en:"Ankles may swell; rest with your feet elevated.",ne:"गोलीगाँठो सुन्निन सक्छ; खुट्टा माथि उठाएर आराम गर्नुहोस्।"}},{w:24,size:{hi:"मक्का जितना (३० सेमी, ६०० ग्राम)",en:"Size of corn (30 cm, 600 g)",ne:"मकैको आकार (३० सेमी, ६०० ग्राम)"},growth:{hi:"जीवन-क्षमता की महत्वपूर्ण सीमा, पैरों के निशान बन चुके हैं! आधुनिक चिकित्सा के लिए यह मील का पत्थर है।",en:"The viability milestone; footprints are fully formed! A landmark in modern medicine.",ne:"जीवन्तताको कोशेढुङ्गा; पाइलाका छापहरू पूर्ण रूपमा बनेका छन्! आधुनिक चिकित्सामा एउटा कोशेढुङ्गा।"},sadhana:{hi:"कृतज्ञता प्रार्थना: रोज़ शाम को इस चमत्कारी यात्रा के लिए धन्यवाद कहें।",en:"Gratitude prayer: every evening, give thanks for this miraculous journey.",ne:"कृतज्ञता प्रार्थना: हरेक साँझ, यो चमत्कारी यात्राको लागि धन्यवाद दिनुहोस्।"},tip:{hi:"इन्हीं दिनों ग्लूकोज़ स्क्रीनिंग टेस्ट होता है, डॉक्टर से पूछें।",en:"The glucose screening test happens around now; ask your doctor.",ne:"ग्लुकोज स्क्रिनिङ परीक्षण अहिले नै हुन्छ; आफ्नो डाक्टरलाई सोध्नुहोस्।"}},{w:25,size:{hi:"फूलगोभी जितना (३३ सेमी)",en:"Size of a cauliflower (33 cm)",ne:"फूलगोभीको आकार (३३ सेमी)"},growth:{hi:"बाल उग रहे हैं और शिशु जानी-पहचानी आवाज़ों पर प्रतिक्रिया देता है।",en:"Hair is growing, and your baby responds to familiar voices.",ne:"कपाल बढ्दैछ, र तपाईंको बच्चाले परिचित आवाजहरूमा प्रतिक्रिया दिन्छ।"},sadhana:{hi:"रोज़ एक ही लोरी गाएं, जन्म के बाद शिशु इसे पहचान लेगा।",en:"Sing the same lullaby every day; after birth your baby will recognize it.",ne:"हरेक दिन एउटै लोरी गाउनुहोस्; जन्मेपछि तपाईंको बच्चाले त्यो चिन्न सक्छ।"},tip:{hi:"कमर दर्द में करवट लेकर सोएं, घुटनों के बीच तकिया रखें।",en:"For back pain, sleep on your side with a pillow between your knees.",ne:"ढाड दुख्ने समस्या भएमा, आफ्नो घुँडाको बीचमा तकिया राखेर छेउमा सुत्नुहोस्।"}},{w:26,size:{hi:"सलाद पत्ता जितना (३६ सेमी, ७६० ग्राम)",en:"Size of a lettuce (36 cm, 760 g)",ne:"सलादको आकार (३६ सेमी, ७६० ग्राम)"},growth:{hi:"फेफड़े पहली सांस के लिए ज़रूरी परत बना रहे हैं और मस्तिष्क बहुत सक्रिय है।",en:"The lungs are developing the coating they need for first breaths, and the brain is very active.",ne:"फोक्सोले पहिलो सास फेर्न आवश्यक पर्ने आवरण विकास गरिरहेको छ, र मस्तिष्क धेरै सक्रिय छ।"},sadhana:{hi:"हर शाम दीया जलाएं, उसकी ज्योति शिशु के उज्ज्वल भविष्य का प्रतीक है।",en:"Light a diya each evening; its flame symbolizes your baby's bright future.",ne:"हरेक साँझ दियो बाल्नुहोस्; यसको ज्वालाले तपाईंको बच्चाको उज्ज्वल भविष्यको प्रतीक हो।"},tip:{hi:"बाईं करवट सोना रक्त प्रवाह के लिए अच्छा होता है।",en:"Sleeping on your left side helps blood flow.",ne:"बायाँ कोल्टे परेर सुत्दा रक्तसञ्चारमा मद्दत पुग्छ।"}},{w:27,size:{hi:"फूलगोभी के फूल जितना (३७ सेमी)",en:"Size of a cauliflower head (37 cm)",ne:"फूलगोभीको टाउकोको आकार (३७ सेमी)"},growth:{hi:"दूसरी तिमाही का समापन! शिशु के सोने-जागने के नियमित चक्र बन गए हैं।",en:"The second trimester ends! Your baby now has regular sleep-wake cycles.",ne:"दोस्रो त्रैमासिक समाप्त हुन्छ! तपाईंको बच्चाको अब नियमित सुत्ने-ब्यूँझने चक्र छ।"},sadhana:{hi:"शिशु के भावी गुणों पर ध्यान करें, यह संकल्प ही गर्भ संस्कार का सार है।",en:"Meditate on your baby's future virtues; this resolve is the heart of Garbh Sanskar.",ne:"आफ्नो बच्चाको भविष्यका गुणहरूमा ध्यान गर्नुहोस्; यो संकल्प गर्भ संस्कारको मुटु हो।"},tip:{hi:"अस्पताल के बैग की सूची बना लें।",en:"Prepare your hospital bag list.",ne:"तपाईंको अस्पतालको झोलाको सूची तयार गर्नुहोस्।"}},{w:28,size:{hi:"बैंगन जितना (३८ सेमी, १ किलो)",en:"Size of an eggplant (38 cm, 1 kg)",ne:"बैंगनको आकार (३८ सेमी, १ किलोग्राम)"},growth:{hi:"आंखें खुल-बंद हो सकती हैं और शिशु REM नींद लेता है, शायद सपने भी देखता है!",en:"The eyes open and close, and your baby experiences REM sleep, perhaps even dreaming!",ne:"आँखा खुल्छ र बन्द हुन्छ, र तपाईंको बच्चाले REM निद्रा अनुभव गर्छ, सायद सपना पनि देख्छ!"},sadhana:{hi:"रोज़ लातों की गिनती करें, यह जुड़ाव का सुंदर अभ्यास है।",en:"Count kicks daily as a beautiful bonding ritual.",ne:"सुन्दर बन्धन अनुष्ठानको रूपमा दैनिक किकहरू गणना गर्नुहोस्।"},tip:{hi:"नियमित जांच करवाएं और रोज़ लातें गिनें।",en:"Keep up regular checkups and count kicks daily.",ne:"नियमित जाँच गरिरहनुहोस् र दैनिक किकहरू गन्नुहोस्।"}},{w:29,size:{hi:"बटरनट कद्दू जितना (३९ सेमी)",en:"Size of a butternut squash (39 cm)",ne:"बटरनट स्क्वासको आकार (३९ सेमी)"},growth:{hi:"मांसपेशियां और फेफड़े परिपक्व हो रहे हैं, शिशु प्रकाश पर प्रतिक्रिया देता है।",en:"Muscles and lungs are maturing; your baby responds to light.",ne:"मांसपेशी र फोक्सो परिपक्व हुँदैछन्; तपाईंको बच्चाले प्रकाशमा प्रतिक्रिया दिन्छ।"},sadhana:{hi:"भगवद्गीता के श्लोक ज़ोर से पढ़ें, ज्ञान की ध्वनि शिशु तक पहुंचती है।",en:"Read Bhagavad Gita verses aloud; the sound of wisdom reaches your baby.",ne:"भागवत गीताका श्लोकहरू ठूलो स्वरमा पढ्नुहोस्; ज्ञानको आवाज तपाईंको बच्चासम्म पुग्छ।"},tip:{hi:"बार-बार पेशाब आना लौट आया है, यह सामान्य है।",en:"Frequent urination returns; this is normal.",ne:"बारम्बार पिसाब फर्कनु; यो सामान्य हो।"}},{w:30,size:{hi:"पत्तागोभी जितना (४० सेमी, १.३ किलो)",en:"Size of a cabbage (40 cm, 1.3 kg)",ne:"बन्दाकोपीको आकार (४० सेमी, १.३ किलोग्राम)"},growth:{hi:"मस्तिष्क में घुमाव और खांचे बन रहे हैं, और फेफड़े परिपक्व होते जा रहे हैं।",en:"The brain is forming its folds and grooves, and the lungs keep maturing.",ne:"मस्तिष्कले आफ्नो तह र खाडलहरू बनाउँदैछ, र फोक्सो परिपक्व हुँदै गइरहेको छ।"},sadhana:{hi:"परिवार का हर सदस्य ज़ोर से शिशु को आशीर्वाद दे।",en:"Let every family member bless the baby aloud.",ne:"परिवारका प्रत्येक सदस्यले बच्चालाई ठूलो स्वरमा आशीर्वाद दिनुहोस्।"},tip:{hi:"सांस फूल सकती है, धीरे-धीरे चलें और आराम करें।",en:"Shortness of breath is common; slow down and rest.",ne:"सास फेर्न गाह्रो हुनु सामान्य छ; बिस्तारै काम गर्नुहोस् र आराम गर्नुहोस्।"}},{w:31,size:{hi:"नारियल जितना (४१ सेमी)",en:"Size of a coconut (41 cm)",ne:"नरिवलको आकार (४१ सेमी)"},growth:{hi:"पांचों इंद्रियां काम कर रही हैं और मस्तिष्क संकेतों को समझ रहा है।",en:"All five senses are working, and the brain is processing signals.",ne:"पाँचै इन्द्रियहरूले काम गरिरहेका छन्, र मस्तिष्कले संकेतहरू प्रशोधन गरिरहेको छ।"},sadhana:{hi:"सीमंतोन्नयन या गोद भराई का पारंपरिक उत्सव मनाएं।",en:"Celebrate the traditional Simantonnayana or godh bharai baby shower.",ne:"परम्परागत सिमन्तोनयन वा भगवान भराई बेबी शावर मनाउनुहोस्।"},tip:{hi:"गोद भराई मनाएं, यह खुशी का समय है।",en:"Celebrate godh bharai; this is a time of joy.",ne:"गोध भराई मनाऔं; यो आनन्दको समय हो।"}},{w:32,size:{hi:"कद्दू जितना (४२ सेमी, १.७ किलो)",en:"Size of a squash (42 cm, 1.7 kg)",ne:"स्क्वासको आकार (४२ सेमी, १.७ किलोग्राम)"},growth:{hi:"पैरों के नाखून बन गए हैं और शिशु सिर नीचे की स्थिति में आ सकता है।",en:"Toenails are formed, and your baby may settle head-down.",ne:"खुट्टाको नङ बन्छन्, र तपाईंको बच्चाको टाउको तलतिर बस्न सक्छ।"},sadhana:{hi:"सुरक्षित प्रसव के लिए संतान गोपाल मंत्र का जाप करें।",en:"Chant the Santan Gopal mantra for a safe delivery.",ne:"सुरक्षित प्रसवको लागि सन्तान गोपाल मन्त्र जप गर्नुहोस्।"},tip:{hi:"शिशु नीचे आने से पेल्विक दबाव बढ़ सकता है।",en:"Pelvic pressure may increase as the baby drops.",ne:"बच्चा खस्दा पेल्भिक प्रेसर बढ्न सक्छ।"}},{w:33,size:{hi:"अनानास जितना (४३ सेमी)",en:"Size of a pineapple (43 cm)",ne:"भुईँकटहरको आकार (४३ सेमी)"},growth:{hi:"खोपड़ी की हड्डियां जन्म के लिए नरम हैं और नींद के स्पष्ट चक्र बन गए हैं।",en:"The skull bones are soft for birth, and distinct sleep cycles are set.",ne:"जन्मको लागि खोपडीको हड्डी नरम हुन्छ, र विशिष्ट निद्रा चक्रहरू सेट हुन्छन्।"},sadhana:{hi:"सहज और सुरक्षित प्रसव की कल्पना करें, सकारात्मक चित्रण शक्ति देता है।",en:"Visualize a smooth, safe delivery; positive imagery gives strength.",ne:"सहज, सुरक्षित डेलिभरीको कल्पना गर्नुहोस्; सकारात्मक कल्पनाले बल दिन्छ।"},tip:{hi:"अनिद्रा सामान्य है, सोने से पहले गर्म दूध पिएं।",en:"Insomnia is common; drink warm milk before bed.",ne:"अनिद्रा सामान्य छ; सुत्नुअघि मनतातो दूध पिउनुहोस्।"}},{w:34,size:{hi:"खरबूजा जितना (४५ सेमी, २.१ किलो)",en:"Size of a cantaloupe (45 cm, 2.1 kg)",ne:"क्यान्टालूपको आकार (४५ सेमी, २.१ किलोग्राम)"},growth:{hi:"तंत्रिका तंत्र परिपक्व हो रहा है और फेफड़े अभ्यास कर रहे हैं।",en:"The nervous system is maturing, and the lungs are practicing.",ne:"स्नायु प्रणाली परिपक्व हुँदैछ, र फोक्सोले अभ्यास गरिरहेको छ।"},sadhana:{hi:"अस्पताल का बैग एक छोटी प्रार्थना के साथ पैक करें।",en:"Pack your hospital bag with a small prayer.",ne:"आफ्नो अस्पतालको झोलामा एउटा सानो प्रार्थना राख्नुहोस्।"},tip:{hi:"अब साप्ताहिक जांच शुरू हो जाती है।",en:"Weekly checkups begin now.",ne:"साप्ताहिक जाँच अब सुरु हुन्छ।"}},{w:35,size:{hi:"हनीड्यू खरबूजा जितना (४६ सेमी, २.४ किलो)",en:"Size of a honeydew (46 cm, 2.4 kg)",ne:"महको आकार (४६ सेमी, २.४ किलोग्राम)"},growth:{hi:"गुर्दे विकसित हो चुके हैं और शिशु हर सप्ताह लगभग २०० ग्राम बढ़ रहा है।",en:"The kidneys are developed, and your baby is gaining about 200 g per week.",ne:"मिर्गौला विकसित हुन्छ, र तपाईंको बच्चाको तौल प्रति हप्ता लगभग २०० ग्राम बढ्दै जान्छ।"},sadhana:{hi:"अपने शिशु के नाम एक पत्र लिखें, यह स्मृति अनमोल होगी।",en:"Write a letter to your baby; this memory will be precious.",ne:"आफ्नो बच्चालाई चिठी लेख्नुहोस्; यो सम्झना अमूल्य हुनेछ।"},tip:{hi:"अस्पताल का रास्ता पहले से जान लें।",en:"Know the hospital route in advance.",ne:"अस्पताल जाने बाटो पहिले नै जान्नुहोस्।"}},{w:36,size:{hi:"रोमेन सलाद जितना (४७ सेमी, २.६ किलो)",en:"Size of a romaine (47 cm, 2.6 kg)",ne:"रोमेनको आकार (४७ सेमी, २.६ किलोग्राम)"},growth:{hi:"वर्निक्स झड़ रहा है और सिर नीचे की ओर आ सकता है।",en:"The vernix is shedding, and the head may engage.",ne:"भर्निक्स झर्दैछ, र टाउको संलग्न हुन सक्छ।"},sadhana:{hi:"आराम करें और शांतिदायक मंत्रों का जाप करें।",en:"Rest and chant peaceful mantras.",ne:"आराम गर्नुहोस् र शान्तिपूर्ण मन्त्रहरू जप गर्नुहोस्।"},tip:{hi:"शिशु नीचे आने से सांस लेना आसान हो जाता है।",en:"Breathing eases as the baby drops.",ne:"बच्चा खस्दा सास फेर्न सजिलो हुन्छ।"}},{w:37,size:{hi:"पेठा जितना (४८ सेमी, २.९ किलो)",en:"Size of a winter melon (48 cm, 2.9 kg)",ne:"जाडोयामको खरबुजाको आकार (४८ सेमी, २.९ किलोग्राम)"},growth:{hi:"पूर्ण अवधि के करीब! मस्तिष्क और फेफड़े अभी भी परिपक्व हो रहे हैं।",en:"Early term! The brain and lungs are still maturing.",ne:"प्रारम्भिक अवधि! मस्तिष्क र फोक्सो अझै परिपक्व हुँदैछन्।"},sadhana:{hi:"बुजुर्गों से अंतिम आशीर्वाद लें।",en:"Receive final blessings from your elders.",ne:"आफ्ना अग्रजहरूबाट अन्तिम आशीर्वाद लिनुहोस्।"},tip:{hi:"शिशु अब किसी भी दिन आ सकता है।",en:"Your baby can arrive any day now.",ne:"तपाईंको बच्चा अब कुनै पनि दिन आउन सक्छ।"}},{w:38,size:{hi:"कद्दू जितना (४९ सेमी, ३ किलो)",en:"Size of a pumpkin (49 cm, 3 kg)",ne:"फर्सीको आकार (४९ सेमी, ३ किलोग्राम)"},growth:{hi:"अंग तैयार हैं और पकड़ मज़बूत है।",en:"The organs are ready, and the grasp is firm.",ne:"अंगहरू तयार छन्, र पकड बलियो छ।"},sadhana:{hi:"मधुर भजनों के साथ शांत दिन बिताएं।",en:"Spend quiet days with soft bhajans.",ne:"नरम भजनहरूसँग शान्त दिनहरू बिताउनुहोस्।"},tip:{hi:"शांत रहें और प्रसव के संकेतों पर ध्यान दें।",en:"Stay calm and watch for the signs of labor.",ne:"शान्त रहनुहोस् र प्रसव पीडाका संकेतहरू हेर्नुहोस्।"}},{w:39,size:{hi:"तरबूज जितना (५० सेमी, ३.३ किलो)",en:"Size of a watermelon (50 cm, 3.3 kg)",ne:"खरबुजाको आकार (५० सेमी, ३.३ किलोग्राम)"},growth:{hi:"फेफड़े मज़बूत हैं और खोपड़ी लचीली है।",en:"The lungs are strong, and the skull is flexible.",ne:"फोक्सो बलियो हुन्छ, र खोपडी लचिलो हुन्छ।"},sadhana:{hi:"स्वागत प्रार्थना करें और पालना तैयार करें।",en:"Say a welcome prayer and prepare the cradle.",ne:"स्वागत प्रार्थना गर र कोक्रो तयार पार।"},tip:{hi:"अब किसी भी दिन, फोन चार्ज रखें।",en:"Any day now; keep your phone charged.",ne:"अब जुनसुकै दिन पनि; आफ्नो फोन चार्जमा राख्नुहोस्।"}},{w:40,size:{hi:"छोटे कद्दू जितना (५१ सेमी, ३.५ किलो)",en:"Size of a small pumpkin (51 cm, 3.5 kg)",ne:"सानो फर्सीको आकार (५१ सेमी, ३.५ किलोग्राम)"},growth:{hi:"जन्मदिन का सप्ताह! सभी तंत्र तैयार हैं।",en:"Birthday week! All systems are go.",ne:"जन्मदिनको हप्ता! सबै प्रणालीहरू काममा छन्।"},sadhana:{hi:"विश्वास और धैर्य रखें, ज्योति अब संसार से मिलेगी।",en:"Trust and be patient; the jyoti meets the world.",ne:"विश्वास गर्नुहोस् र धैर्य गर्नुहोस्; ज्योतिले संसारलाई भेट्छ।"},tip:{hi:"यदि तारीख निकल जाए तो डॉक्टर विकल्पों पर चर्चा करेंगे।",en:"If overdue, your doctor will discuss options.",ne:"यदि ढिलो भयो भने, तपाईंको डाक्टरले विकल्पहरू छलफल गर्नेछन्।"}}];